// Signature (Conceptual)
// int open(const char *path, int flags, mode_t mode);

// Open existing file for reading
int fd_read = open("/etc/hosts", O_RDONLY);

// Create new file (0644 permissions)
mode_t new_file_mode = 0644; // rw-r--r--

int fd_create = open("output.dat",
                     O_WRONLY | O_CREAT | O_TRUNC,
                     new_file_mode);

// Check result
if (fd_create == -1) {
    // Handle error (EACCES, ENOENT, etc.)
}

if (fd_read > 0) close(fd_read);
if (fd_create > 0) close(fd_create);
